import{_ as i,o as t,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/profile/3-3-3-view-client-profile/report3_spec.md","filePath":"feature/profile/3-3-3-view-client-profile/report3_spec.md"}'),s={name:"feature/profile/3-3-3-view-client-profile/report3_spec.md"};function o(l,e,a,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[r("<p><strong>3.3.3 View Client Profile</strong></p><p>&gt; V2 (2026-10-02): ClientProfile reworked — owned by the User, independent of any Agency.</p><p><strong>Function Trigger</strong></p><p>Begins when a user opens their own list of Client Profiles (&quot;My Brand Profiles&quot;), or when an Agency Manager/Owner opens a workspace&#39;s Client list to manage collaborating clients.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Any signed-in user, viewing the Client Profiles they personally own; Agency members (Owner/Manager) when viewing a workspace&#39;s Client list (<code>/workspaces/{id}/clients</code>).</li><li><strong>Purpose</strong>: Let a user manage the Client Profiles they own — one person may represent several brands (e.g. Nike, Adidas) and hold one profile per brand, none of which belong to any Agency. A profile is reused across every workspace/Agency the user collaborates with.</li><li><strong>Interface</strong>: The personal screen at /client-profiles lists every Client Profile the signed-in user owns — no Agency context required. A separate Workspace Client list, at /workspaces/{id}/clients, shows every WorkspaceMember with role CLIENT currently linked to that workspace (via client_profile_id).</li><li><strong>Data Processing</strong>: The system resolves the caller&#39;s identity from the access token and returns every Client Profile where userId matches the caller. For the workspace list, the system returns the workspace&#39;s active CLIENT members joined with their linked Client Profile for display.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — My Brand Profiles (/client-profiles):</p><ul><li>Center: list of every Client Profile the signed-in user owns — display name, company, contact details, logo.</li><li>Buttons: Create new profile, Edit, Delete (blocked if linked to an active workspace membership).</li></ul><p>Figure — Workspace Client List (/workspaces/{id}/clients):</p><ul><li>Center: list of active CLIENT members of this workspace — display name (from the linked Client Profile), joined date, status.</li><li>Buttons: &quot;Add client&quot; (Owner/Manager only) — opens an invite-by-email dialog (see 3.4.7 for the invite flow).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: None beyond the caller&#39;s identity (My Brand Profiles); the workspace identifier, for the Workspace Client list.</li><li><strong>Input optional</strong>: None.</li><li><strong>System data</strong>: client_profiles — id, userId, displayName, company, phone, note, logoUrl, website, industry, location, description, socialLinks, plus brand fields, createdAt, updatedAt. The link to a workspace is client_profile_id on workspace_members, not any field on client_profiles.</li><li><strong>Output</strong>: Every Client Profile owned by the caller, or the list of active CLIENT members for one workspace.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-41 (reworked)</strong>: A Client Profile belongs to exactly one User and is never scoped to an Agency. One user may hold several independent Client Profiles — one per brand/customer they represent — completely unrelated to how many Agencies or workspaces they collaborate with.</li><li>The same Client Profile can be linked to any number of workspaces across any number of Agencies simultaneously.</li><li>A Client Profile is created either explicitly by its owner, or inline during a CLIENT invitation accept flow — never implicitly, and never keyed by an Agency.</li><li><strong>BR-38</strong>: Client access is scoped by workspace membership — a client can only see/approve content in workspaces where their Client Profile is actively linked. A Client Profile is independent of the user&#39;s own User Profile (3.3.1).</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing, expired, or invalid access token → Display: <strong>MSG22</strong>.</li><li>Workspace Client list: missing or invalid workspace identifier → 404 WORKSPACE_NOT_FOUND.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user opens &quot;My Brand Profiles&quot; (/client-profiles).</li><li>The system resolves the caller&#39;s identity from the access token.</li><li>The system returns every Client Profile where userId matches the caller.</li><li>The application renders the list — one card per brand the user represents.</li><li>Alternatively, an Agency Manager/Owner opens a workspace&#39;s Client list; the system returns that workspace&#39;s active CLIENT members, and the application displays them with an &quot;Add client&quot; action.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>N.a1: Missing, expired, or invalid access token at any step, the system displays <strong>MSG22</strong>. N.a2: The user signs in again at /login (3.2.2).</li><li>5.a1: Invalid or missing workspace identifier → 404 WORKSPACE_NOT_FOUND. 5.a2: The application returns to the workspace list.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Every Client Profile owned by the caller is displayed with the values currently stored for it, independent of any Agency context.</li><li>The Workspace Client list reflects the workspace&#39;s current active CLIENT members only.</li><li>No data is changed; the operation is read-only.</li></ul>",17)])])}const h=i(s,[["render",o]]);export{u as __pageData,h as default};
